package com.lims.model;
import java.math.BigDecimal;
public class Product {private int productId,productLineId;private String productCode,productName,lineName,brandName,cpu,ram,storage,gpu,screen,status;private BigDecimal unitPrice;public int getProductId(){return productId;}public void setProductId(int v){productId=v;}public int getProductLineId(){return productLineId;}public void setProductLineId(int v){productLineId=v;}public String getProductCode(){return productCode;}public void setProductCode(String v){productCode=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public String getLineName(){return lineName;}public void setLineName(String v){lineName=v;}public String getBrandName(){return brandName;}public void setBrandName(String v){brandName=v;}public String getCpu(){return cpu;}public void setCpu(String v){cpu=v;}public String getRam(){return ram;}public void setRam(String v){ram=v;}public String getStorage(){return storage;}public void setStorage(String v){storage=v;}public String getGpu(){return gpu;}public void setGpu(String v){gpu=v;}public String getScreen(){return screen;}public void setScreen(String v){screen=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public BigDecimal getUnitPrice(){return unitPrice;}public void setUnitPrice(BigDecimal v){unitPrice=v;}}
